def compute_pseudo_inverse(mask):
    mask_flat = mask.view(-1)
    mask_indices = mask_flat.nonzero(as_tuple=False).squeeze()
    A_cross = torch.zeros_like(mask_flat, dtype=torch.float32)
    A_cross[mask_indices] = 1
    A_cross = A_cross.view(mask.shape)
    return A_cross


def save_to_image(tensor, filename):
    to_save = (tensor + 1) / 2
    to_save = to_save.clamp(0, 1)

    # Convert to PIL Image
    transform = ToPILImage()
    img = transform(to_save)

    # Save the image
    img.save(filename)


def compute_kl_div_parallel(x_0, observation, operator, noise, num_subsets=8):
    # Ensure all inputs are on the same device
    device = x_0.device
    
    # Compute the difference
    diff = operator(x_0) - observation
    # diff = x_0[:, :, ::4, ::4] - original_image[:, :, ::4, ::4]

    # Flatten the entire image
    diff_flat = diff.reshape(-1)
    
    # Compute the total number of elements
    total_elements = diff_flat.numel()
    
    # Compute the number of elements per subset
    elements_per_subset = total_elements // num_subsets
    
    # Create random indices for each subset
    indices = torch.randperm(total_elements, device=device).view(num_subsets, -1)
    
    # Function to compute KL divergence for a subset
    def compute_subset_kl(subset_indices):
        subset = diff_flat.index_select(0, subset_indices)
        sample_mean = subset.mean()
        sample_var = ((subset - sample_mean) ** 2).mean()
        kl_div = torch.log(sample_var.sqrt() / noise) + (noise**2 + sample_mean**2) / (2*sample_var)
        return sample_mean, sample_var, kl_div
    
    # Compute KL divergence for each subset
    results = [compute_subset_kl(indices[i]) for i in range(num_subsets)]
    
    # Unpack results
    sample_means, sample_vars, kl_divs = zip(*results)
    
    # Convert to tensors
    sample_means = torch.stack(sample_means)
    sample_vars = torch.stack(sample_vars)
    kl_divs = torch.stack(kl_divs)
    
    # Compute the total KL divergence
    total_kl_div = kl_divs.mean()
    
    # Print results
    print(f"Sample means: {sample_means}")
    print(f"Sample variances: {sample_vars}")
    print(f"KL divergences: {kl_divs}")
    print(f"Total KL divergence: {total_kl_div}")
    
    return total_kl_div


def compute_kl_div_spatial(x_0, observation, super_res_operator, noise, num_subsets=8):
    # Ensure all inputs are on the same device
    device = x_0.device
    
    # Compute the difference
    diff = super_res_operator.forward(x_0) - observation
    # diff = x_0[:, :, ::4, ::4] - original_image[:, :, ::4, ::4]

    # Get the shape of the difference tensor
    b, c, h, w = diff.shape
    
    # Calculate the size of each patch
    patch_h = h // int(num_subsets)
    patch_w = w // int(num_subsets)
    
    # Reshape the difference tensor into patches
    patches = diff.unfold(2, patch_h, patch_h).unfold(3, patch_w, patch_w)
    patches = patches.contiguous().view(b, c, -1, patch_h, patch_w)
    
    # Flatten each patch
    flat_patches = patches.view(b, -1, patch_h * patch_w * 3)
    
    # Compute mean and variance for each patch
    patch_means = flat_patches.mean(dim=-1)
    patch_vars = (flat_patches **2).mean(dim=-1)
    
    # Compute KL divergence for each patch
    kl_divs = torch.log(patch_vars.sqrt() / noise) + (noise**2 + patch_means**2) / (2 * patch_vars)
    # Sum KL divergence across channels and patches
    total_kl_div = kl_divs.mean()
    
    # Print results
    print(f"Patch means shape: {patch_means}")
    print(f"Patch variances shape: {patch_vars}")
    print(f"KL divergences shape: {kl_divs}")
    print(f"Total KL divergence: {total_kl_div.item()}")
    
    return total_kl_div


class DDPMPipeline(DiffusionPipeline):
    r"""
    Pipeline for image generation.

    This model inherits from [`DiffusionPipeline`]. Check the superclass documentation for the generic methods
    implemented for all pipelines (downloading, saving, running on a particular device, etc.).

    Parameters:
        unet ([`UNet2DModel`]):
            A `UNet2DModel` to denoise the encoded image latents.
        scheduler ([`SchedulerMixin`]):
            A scheduler to be used in combination with `unet` to denoise the encoded image. Can be one of
            [`DDPMScheduler`], or [`DDIMScheduler`].
    """

    model_cpu_offload_seq = "unet"

    def __init__(self, unet, scheduler):
        super().__init__()
        self.register_modules(unet=unet, scheduler=scheduler)

    @torch.no_grad()
    def __call__(
        self,
        batch_size: int = 1,
        generator: Optional[Union[torch.Generator, List[torch.Generator]]] = None,
        num_inference_steps: int = 1000,
        K=10,
        output_type: Optional[str] = "pil",
        return_dict: bool = True,
        original_image = None,
        observation = None,
        noise = None,
        dps_model=None,
        operator=None,
        original_image_denoised=None
    ) -> Union[ImagePipelineOutput, Tuple]:
        r"""
        The call function to the pipeline for generation.

        Args:
            batch_size (`int`, *optional*, defaults to 1):
                The number of images to generate.
            generator (`torch.Generator`, *optional*):
                A [`torch.Generator`](https://pytorch.org/docs/stable/generated/torch.Generator.html) to make
                generation deterministic.
            num_inference_steps (`int`, *optional*, defaults to 1000):
                The number of denoising steps. More denoising steps usually lead to a higher quality image at the
                expense of slower inference.
            output_type (`str`, *optional*, defaults to `"pil"`):
                The output format of the generated image. Choose between `PIL.Image` or `np.array`.
            return_dict (`bool`, *optional*, defaults to `True`):
                Whether or not to return a [`~pipelines.ImagePipelineOutput`] instead of a plain tuple.

        Example:

        ```py
        >>> from diffusers import DDPMPipeline

        >>> # load model and scheduler
        >>> pipe = DDPMPipeline.from_pretrained("google/ddpm-cat-256")

        >>> # run pipeline in inference (sample random noise and denoise)
        >>> image = pipe().images[0]

        >>> # save image
        >>> image.save("ddpm_generated_image.png")
        ```

        Returns:
            [`~pipelines.ImagePipelineOutput`] or `tuple`:
                If `return_dict` is `True`, [`~pipelines.ImagePipelineOutput`] is returned, otherwise a `tuple` is
                returned where the first element is a list with the generated images
        """
        # Sample gaussian noise to begin loop
        if isinstance(self.unet.config.sample_size, int):
            image_shape = (
                batch_size,
                self.unet.config.in_channels,
                self.unet.config.sample_size,
                self.unet.config.sample_size,
            )
        else:
            image_shape = (batch_size, self.unet.config.in_channels, *self.unet.config.sample_size)

